def build_references(seed_value: int, count: int) -> list[str]:
    """Build ``count`` deterministic, realistic-looking APA 7 references.

    The DOIs use the real registrant prefixes of the journals named, but the
    suffixes are invented; the seed command marks the whole set as example data.
    """
    rng = random.Random(seed_value)
    references: list[str] = []
    used: set[tuple[int, int]] = set()
    for index in range(count):
        while True:
            author_index = rng.randrange(len(_REF_AUTHORS))
            title_index = rng.randrange(len(_REF_TITLES))
            if (author_index, title_index) not in used:
                used.add((author_index, title_index))
                break
        journal, prefix = rng.choice(_REF_JOURNALS)
        year = rng.randint(2009, 2025)
        volume = rng.randint(8, 140)
        issue = rng.randint(1, 6)
        first_page = rng.randint(1, 900)
        last_page = first_page + rng.randint(12, 40)
        doi = f"{prefix}/example.{year}.{rng.randint(1000, 9999)}"
        references.append(
            f"{_REF_AUTHORS[author_index]} ({year}). {_REF_TITLES[title_index]}. "
            f"*{journal}*, {volume}({issue}), {first_page}–{last_page}. "
            f"https://doi.org/{doi}"
        )
    return references


