            {"given": "Marta", "family": "Kowalska", "affiliation": {"en": "Warsaw School of Economics", "uz": "Varshava iqtisodiyot maktabi", "ru": "Варшавская школа экономики"}, "city": "Warsaw", "country": "PL", "orcid": "0000-0002-1000-0051", "corresponding": True, "credit": ["Conceptualization", "Formal analysis", "Writing – original draft"]},
